p = 'listing_scraper.py'; s = open(p).read()
anchor = 'def build_selection_report(photos: list, selection: dict, scene_count_requested=None, premium: bool = False) -> dict:'
assert s.count(anchor) == 1 and 'def pick_alternative_photo' not in s
FUNC = 'def pick_alternative_photo(report: dict, category: str, exclude_urls=()) -> dict:\n    """2026-11-12 (Michele, point 3): the scene was rejected twice with its photo -> the best OTHER photo of the same room that no scene uses.\n    No second selection procedure: the pool goes through the same shared step as the first selection (_categorize_and_rank_photos: ranking, room-feature\n    check, quality filter, all on the photo as the video uses it). A photo whose room feature is NOT visible is never an alternative.\n    report = the job\'s selection_report (candidate_urls by category + selected). Returns {"photo": dict | None, "reason": str, "considered": int}.\n    "photo" None = nothing to try: the caller stops and leaves the decision to the operator. Never raises."""\n    try:\n        used = set(exclude_urls or ())\n        for lst in ((report or {}).get("selected") or {}).values():\n            for sel in lst:\n                used.update(u for u in (sel.get("url"), sel.get("original_url"), sel.get("url_used")) if u)\n        urls = [u for u in (((report or {}).get("candidate_urls") or {}).get(category) or []) if u and u not in used]\n        if not urls:\n            return {"photo": None, "reason": "no other photo of this room", "considered": 0}\n        by = _categorize_and_rank_photos([{"url": u, "category": category} for u in urls], [category])\n        pool = by.get(category) or []\n        for p in pool:\n            if p.get("feature_visible") is False:\n                continue\n            return {"photo": p, "reason": "ok", "considered": len(urls)}\n        return {"photo": None, "reason": "no other photo of this room passes the quality / room-feature checks", "considered": len(urls)}\n    except Exception as e:\n        log.warning(f"[Scraper] Alternative photo failed for {category}: {e}")\n        return {"photo": None, "reason": "error: " + str(e)[:120], "considered": 0}\n\n\n'
open(p, 'w').write(s.replace(anchor, FUNC + anchor))
open('test_alt_photo.py', 'w').write('"""pick_alternative_photo (point 3): the best other photo of the same room, through the SHARED selection step; otherwise nothing (the operator decides)."""\nimport os, sys, types\nsys.path.insert(0, os.getcwd())\ntry:\n    import anthropic  # noqa\nexcept Exception:\n    m = types.ModuleType("anthropic"); m.Anthropic = object; sys.modules["anthropic"] = m\nimport listing_scraper as ls\nres = []\ndef check(name, ok, info=""):\n    res.append(bool(ok)); print(("PASS " if ok else "FAIL ") + name + ("" if ok else "  -> " + str(info)))\n\nREPORT = {"selected": {"bathrooms": [{"url": "B1", "url_used": "B1u", "original_url": None}], "kitchen": [{"url": "K1"}]},\n          "candidate_urls": {"bathrooms": ["B1", "B2", "B3", "B4"], "kitchen": ["K1"], "bedrooms": ["D1", "D2"]}}\nseen = {}\ndef fake_shared(photos, categories):\n    seen["urls"] = [p["url"] for p in photos]; seen["cats"] = list(categories)\n    return {categories[0]: [dict(p, **seen.get("tags", {}).get(p["url"], {})) for p in photos]}\nls._categorize_and_rank_photos = fake_shared\n\nseen["tags"] = {}\nr = ls.pick_alternative_photo(REPORT, "bathrooms")\ncheck("A1 the photo already used is never an alternative; the pool goes through the shared step", seen["urls"] == ["B2", "B3", "B4"] and seen["cats"] == ["bathrooms"], seen)\ncheck("A2 first of the ranked pool is returned", r["photo"]["url"] == "B2" and r["reason"] == "ok" and r["considered"] == 3, r)\nseen["tags"] = {"B2": {"feature_visible": False}}\nr = ls.pick_alternative_photo(REPORT, "bathrooms")\ncheck("A3 a photo whose room feature is NOT visible is skipped", r["photo"]["url"] == "B3", r)\nseen["tags"] = {"B2": {"feature_visible": False}, "B3": {"feature_visible": False}, "B4": {"feature_visible": False}}\nr = ls.pick_alternative_photo(REPORT, "bathrooms")\ncheck("A4 none passes -> no photo, reason says why", r["photo"] is None and "pass" in r["reason"], r)\nr = ls.pick_alternative_photo(REPORT, "kitchen")\ncheck("A5 a room with a single photo (already used) -> nothing to try", r["photo"] is None and r["reason"] == "no other photo of this room", r)\nseen["tags"] = {}\nr = ls.pick_alternative_photo(REPORT, "bathrooms", exclude_urls=["B2"])\ncheck("A6 a photo already tried as alternative is excluded", r["photo"]["url"] == "B3", r)\nseen["tags"] = {"B2": {"feature_visible": None}}\nr = ls.pick_alternative_photo(REPORT, "bathrooms")\ncheck("A7 feature check unknown (None) keeps the photo", r["photo"]["url"] == "B2", r)\ndef boom(photos, categories): raise RuntimeError("down")\nls._categorize_and_rank_photos = boom\nr = ls.pick_alternative_photo(REPORT, "bathrooms")\ncheck("A8 any error -> no photo (the operator decides), never raises", r["photo"] is None and r["reason"].startswith("error"), r)\ncheck("A9 empty / missing report -> no photo, never raises", ls.pick_alternative_photo({}, "bathrooms")["photo"] is None and ls.pick_alternative_photo(None, "bathrooms")["photo"] is None)\nprint("%d/%d PASS" % (sum(res), len(res)))\nsys.exit(0 if all(res) else 1)\n')
print('ok')
